#include <cstdio>
#include <cstring>
#include <algorithm>
#define LOOP(i,a,b) for(int i=a;i<=b;i++)
#define REV_LOOP(i,a,b) for(int i=a;i>=b;i--)
using namespace std;

typedef long long ll;

const int MAXN=262144;

int L,n,k,Mo,len,bit[20],fac[MAXN],inv[MAXN],cnt[MAXN],g[20][MAXN],f[20][MAXN],h[20],p[20];

int qpow(int base,int exp) {
	int res=1;
	while (exp>0) {
		if (exp&1) res=(ll)res*base%Mo;
		base=(ll)base*base%Mo;
		exp>>=1;
	}
	return res;
}

void add_mod(int &x,int y) {x=x+y>=Mo?x+y-Mo:x+y;}
void sub_mod(int &x,int y) {x=x-y<0?x-y+Mo:x-y;}
void FWT_transform(int *a,int len) {
	for(int i=1;i<len;i<<=1) {
		for(int j=0;j<len;j+=i<<1) {
			for(int k=0;k<i;k++) {
				add_mod(a[j+k+i],a[j+k]);
			}
		}
	}
}
void IFWT_transform(int *a,int len) {
	for(int i=1;i<len;i<<=1) {
		for(int j=0;j<len;j+=i<<1) {
			for(int k=0;k<i;k++) {
				sub_mod(a[j+k+i],a[j+k]);
			}
		}
	}
}

void compute_logarithm(int *a,int *b,int n) {
	b[0]=0;
	LOOP(i,1,n) {
		b[i]=(ll)a[i]*i%Mo;
		LOOP(j,1,i-1) {
			b[i]+=(Mo-(ll)b[j]*a[i-j]%Mo*j)%Mo;
		}
		b[i]=(ll)b[i]*qpow(i,Mo-2)%Mo;
	}
}

void compute_exponential(int *a,int *b,int n) {
	b[0]=1;
	LOOP(i,1,n) {
		b[i]=0;
		LOOP(j,1,i) {
			b[i]+=(ll)a[j]*b[i-j]%Mo*j%Mo;
		}
		b[i]=(ll)b[i]*qpow(i,Mo-2)%Mo;
	}
}

int main() {
	scanf("%d%d%d",&L,&k,&Mo);
	int total=1;
	REP(i,0,L-1) total=(ll)total*k%Mo;
	if (L&1) {
		printf("%d\n",total);
		return 0;
	}
	fac[0]=1; LOOP(i,1,L) fac[i]=(ll)fac[i-1]*i%Mo;
	inv[L]=qpow(fac[L],Mo-2); REV_LOOP(i,L-1,0) inv[i]=(ll)inv[i+1]*(i+1)%Mo;
	LOOP(s,1,L) cnt[s]=cnt[s^(s&-s)]+1;
	LOOP(i,0,18) if (L>>i&1) bit[++n]=1<<i;
	len=1<<n;
	LOOP(i,0,len-1) {
		int s=0;
		LOOP(j,1,n) if (i>>(j-1)&1) s+=bit[j];
		g[cnt[i]][i]=inv[s];
	}
	FWT_transform(g[0],len);
	FWT_transform(g[1],len);
	FWT_transform(g[2],len);
	LOOP(s,0,len-1) {
		LOOP(i,0,n) h[i]=g[i][s];
		get_ln(h,p,n);
		LOOP(i,0,n) p[i]=(ll)p[i]*k%Mo;
		get_exp(p,h,n);
		LOOP(i,0,n) f[i][s]=h[i];
	}
	IFWT_transform(f[n],len);
	int answer=(ll)f[n][len-1]*fac[L]%Mo;
	answer=(total-answer+Mo)%Mo;
	printf("%d\n",answer);
	return 0;
}
